import { Controller, Put, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 서명 이미지는 data URL(base64) 문자열로 받는다. 허용 형식은 png·jpg·jpeg·gif.
const IMAGE_PATTERN = /^data:image\/(png|jpeg|jpg|gif);base64,([A-Za-z0-9+/]+={0,2})$/;
// 가정: 서명 이미지 최대 크기 2MB
const MAX_IMAGE_BYTES = 2 * 1024 * 1024;
// 가정: 소유 대상 유형 값 목록이 미확정이라 서명 이미지는 이 값으로 연결한다
const SIGNATURE_OWNER_TYPE = 'EMPLOYEE_SIGNATURE';
// 가정: 텍스트 서명 최대 길이 (employee_signature.signature_text VARCHAR(200))
const MAX_SIGNATURE_TEXT = 200;

@Controller('api/v1')
export class FnSfr029202Xe5a391Controller {
  @Put('/employee-signatures/me')
  async saveEmployeeSignature(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const data = checks.inputOf(req.body);
    const signatureType = typeof data['signatureType'] === 'string' ? data['signatureType'] : '';
    if (signatureType !== 'TEXT' && signatureType !== 'IMAGE') {
      throw new ApiError(400, 'VALIDATION_FAILED', '서명 유형은 TEXT 또는 IMAGE 중에서 선택해야 합니다.');
    }
    const rawText = data['signatureText'];
    const rawImage = data['signatureImage'];
    let signatureText: string | null = null;
    let imageBase64 = '';
    let imageExt = '';
    let imageBytes = 0;
    if (signatureType === 'TEXT') {
      if (typeof rawText !== 'string' || rawText.trim() === '') {
        throw new ApiError(422, 'SIGNATURE_VALUE_REQUIRED', '텍스트 서명을 입력해 주세요.');
      }
      if (rawText.length > MAX_SIGNATURE_TEXT) {
        throw new ApiError(400, 'VALIDATION_FAILED', '서명 텍스트는 200자 이하로 입력해 주세요.');
      }
      signatureText = rawText.trim();
    } else {
      if (typeof rawImage !== 'string' || rawImage.trim() === '') {
        throw new ApiError(422, 'SIGNATURE_VALUE_REQUIRED', '서명 이미지를 선택해 주세요.');
      }
      const matched = IMAGE_PATTERN.exec(rawImage.trim());
      if (!matched) {
        throw new ApiError(422, 'SIGNATURE_IMAGE_INVALID', '서명 이미지는 PNG, JPG, GIF 형식만 사용할 수 있습니다.');
      }
      imageExt = matched[1] === 'jpeg' ? 'jpg' : matched[1];
      imageBase64 = matched[2];
      const padding = imageBase64.endsWith('==') ? 2 : imageBase64.endsWith('=') ? 1 : 0;
      imageBytes = Math.floor((imageBase64.length * 3) / 4) - padding;
      if (imageBytes <= 0 || imageBytes > MAX_IMAGE_BYTES) {
        throw new ApiError(422, 'SIGNATURE_IMAGE_INVALID', '서명 이미지 크기가 올바르지 않습니다. 2MB 이하의 이미지를 올려 주세요.');
      }
    }
    return transaction(async (db) => {
      const employees = await db.query(
        'SELECT employee_id FROM employee WHERE employee_id = CAST(:userId AS bigint)',
        { userId: user.id },
      );
      if (employees.length === 0) {
        throw new ApiError(404, 'NOT_FOUND', '임직원 정보를 찾을 수 없습니다.');
      }
      let attachmentId: number | null = null;
      if (signatureType === 'IMAGE') {
        const attached = await db.query(
          'INSERT INTO attachment (uploader_id, owner_type, file_name, file_ext, file_size, content_hash, created_at, updated_at) '
            + "VALUES (CAST(:userId AS bigint), :ownerType, :fileName, :fileExt, CAST(:fileSize AS bigint), encode(sha256(convert_to(:content, 'UTF8')), 'hex'), now(), now()) "
            + 'RETURNING attachment_id AS "attachmentId"',
          {
            userId: user.id,
            ownerType: SIGNATURE_OWNER_TYPE,
            fileName: 'signature.' + imageExt,
            fileExt: imageExt,
            fileSize: String(imageBytes),
            content: imageBase64,
          },
        );
        attachmentId = Number(attached[0]['attachmentId']);
      }
      const saved = await db.query(
        'INSERT INTO employee_signature (employee_id, signature_type, signature_text, attachment_id, created_at, updated_at) '
          + 'VALUES (CAST(:userId AS bigint), :signatureType, :signatureText, CAST(:attachmentId AS bigint), now(), now()) '
          + 'ON CONFLICT (employee_id) DO UPDATE SET signature_type = EXCLUDED.signature_type, '
          + 'signature_text = EXCLUDED.signature_text, attachment_id = EXCLUDED.attachment_id, updated_at = now() '
          + 'RETURNING employee_signature_id AS "employeeSignatureId", signature_type AS "signatureType", '
          + 'signature_text AS "signatureText", attachment_id AS "attachmentId"',
        {
          userId: user.id,
          signatureType,
          signatureText,
          attachmentId: attachmentId === null ? null : String(attachmentId),
        },
      );
      if (attachmentId !== null) {
        await db.execute(
          'UPDATE attachment SET owner_id = CAST(:ownerId AS bigint), updated_at = now() WHERE attachment_id = CAST(:attachmentId AS bigint)',
          { ownerId: String(saved[0]['employeeSignatureId']), attachmentId: String(attachmentId) },
        );
      }
      const row = saved[0];
      return {
        employeeSignatureId: Number(row['employeeSignatureId']),
        signatureType: row['signatureType'],
        signatureText: row['signatureText'],
        attachmentId: row['attachmentId'] === null ? null : Number(row['attachmentId']),
      };
    });
  }
}

