import { useState } from 'react';
import {
  Badge,
  Band,
  DataTable,
  Drawer,
  Field,
  Form,
  LookupSelect,
  NumberInput,
  RefName,
  Select,
  TextInput,
  Tiles,
  call,
} from '../kit';
import type { PageProps, Row } from '../kit';

export default function FnSfr029202Xe5a391Page({ role, notify }: PageProps) {
  const [signatures, setSignatures] = useState<Row[]>([]);
  const [documents, setDocuments] = useState<Row[]>([]);
  const [openSignature, setOpenSignature] = useState(false);
  const [openDocument, setOpenDocument] = useState(false);

  const [signatureType, setSignatureType] = useState('TEXT');
  const [signatureText, setSignatureText] = useState('');
  const [signatureImage, setSignatureImage] = useState('');
  const [imageName, setImageName] = useState('');

  const [approvalFormId, setApprovalFormId] = useState<number | string>('');
  const [title, setTitle] = useState('');
  const [body, setBody] = useState('');
  const [linkedBusinessType, setLinkedBusinessType] = useState('');
  const [linkedBusinessId, setLinkedBusinessId] = useState<number | string>('');

  const current = signatures.length > 0 ? signatures[0] : undefined;

  function startSignature() {
    setSignatureType('TEXT');
    setSignatureText('');
    setSignatureImage('');
    setImageName('');
    setOpenSignature(true);
  }

  function startDocument() {
    setApprovalFormId('');
    setTitle('');
    setBody('');
    setLinkedBusinessType('');
    setLinkedBusinessId('');
    setOpenDocument(true);
  }

  function readImage(file: File | undefined) {
    if (!file) {
      setSignatureImage('');
      setImageName('');
      return;
    }
    const reader = new FileReader();
    reader.onload = () => {
      setSignatureImage(String(reader.result));
      setImageName(file.name);
    };
    reader.readAsDataURL(file);
  }

  async function submitSignature() {
    if (signatureType === 'TEXT' && signatureText.trim() === '') {
      throw new Error('텍스트 서명을 입력해 주세요.');
    }
    if (signatureType === 'IMAGE' && signatureImage === '') {
      throw new Error('서명 이미지를 선택해 주세요.');
    }
    const body: Row = { signatureType };
    if (signatureType === 'TEXT') {
      body.signatureText = signatureText.trim();
    } else {
      body.signatureImage = signatureImage;
    }
    const saved = await call('PUT', '/employee-signatures/me', role, body);
    setSignatures([saved, ...signatures]);
    setOpenSignature(false);
    notify('서명을 저장했습니다.');
  }

  async function submitDocument() {
    if (approvalFormId === '') {
      throw new Error('결재양식을 선택해 주세요.');
    }
    if (title.trim() === '') {
      throw new Error('문서 제목을 입력해 주세요.');
    }
    if (linkedBusinessType.trim() === '') {
      throw new Error('연계 업무 유형을 입력해 주세요.');
    }
    if (linkedBusinessId === '') {
      throw new Error('연계 업무 식별자를 입력해 주세요.');
    }
    const created = await call('POST', '/approval-documents', role, {
      approvalFormId,
      title: title.trim(),
      body,
      linkedBusinessType: linkedBusinessType.trim(),
      linkedBusinessId,
    });
    setDocuments([{ ...created, title: title.trim(), approvalFormId }, ...documents]);
    setOpenDocument(false);
    notify('결재문서를 저장했습니다.');
  }

  return (
    <div className={'bento'}>
      <section className={'box span-4'}>
        <h2>내 서명</h2>
        <Tiles
          items={[
            ['서명 유형', current ? <Badge value={current.signatureType} /> : '-'],
            ['서명', current ? String(current.signatureText ?? '이미지 서명') : '-'],
          ]}
        />
        <Band total={signatures.length}>
          <button type={'button'} onClick={startSignature}>서명 설정</button>
        </Band>
      </section>

      <section className={'box span-8'}>
        <h2>서명 설정 내역</h2>
        <DataTable
          rows={signatures}
          empty={'이 화면에서 설정한 서명이 없습니다.'}
          columns={[
            { key: 'employeeSignatureId', label: '임직원 결재 서명 ID' },
            { key: 'signatureType', label: '서명 유형', render: (r) => <Badge value={r.signatureType} /> },
            { key: 'signatureText', label: '서명 텍스트' },
            {
              key: 'attachmentId',
              label: '서명 이미지 첨부파일',
              render: (r) => (r.attachmentId ? <RefName table={'attachment'} role={role} value={r.attachmentId} /> : '-'),
            },
          ]}
        />
      </section>

      <section className={'box span-12'}>
        <h2>양식 기안</h2>
        <Band total={documents.length}>
          <button type={'button'} onClick={startDocument}>양식으로 기안</button>
        </Band>
        <DataTable
          rows={documents}
          empty={'이 화면에서 기안한 문서가 없습니다.'}
          columns={[
            { key: 'documentNumber', label: '문서번호' },
            { key: 'title', label: '문서 제목' },
            {
              key: 'approvalFormId',
              label: '결재양식',
              render: (r) => <RefName table={'approval_form'} role={role} value={r.approvalFormId} />,
            },
            { key: 'approvalStatus', label: '결재 진행 상태', render: (r) => <Badge value={r.approvalStatus} /> },
          ]}
        />
      </section>

      {openSignature && (
        <Drawer title={'서명 설정'} onClose={() => setOpenSignature(false)}>
          <Form onSubmit={submitSignature} submit={'저장'}>
            <Field label={'서명 유형'} required>
              <Select
                value={signatureType}
                onChange={setSignatureType}
                options={[['TEXT', '텍스트 서명'], ['IMAGE', '이미지 서명']]}
              />
            </Field>
            {signatureType === 'TEXT' ? (
              <Field label={'서명 텍스트'} required wide>
                <TextInput value={signatureText} onChange={setSignatureText} />
              </Field>
            ) : (
              <Field label={'서명 이미지'} required wide hint={'PNG, JPG, GIF 형식 (2MB 이하)'}>
                <input
                  type={'file'}
                  accept={'image/png,image/jpeg,image/gif'}
                  onChange={(e) => readImage(e.target.files ? e.target.files[0] : undefined)}
                />
                <span>{imageName}</span>
              </Field>
            )}
          </Form>
        </Drawer>
      )}

      {openDocument && (
        <Drawer title={'양식으로 기안'} onClose={() => setOpenDocument(false)}>
          <Form onSubmit={submitDocument} submit={'저장'}>
            <Field label={'결재양식'} required>
              <LookupSelect
                table={'approval_form'}
                role={role}
                value={approvalFormId}
                onChange={setApprovalFormId}
                placeholder={'간편 기안 또는 요약문 양식 선택'}
              />
            </Field>
            <Field label={'문서 제목'} required wide>
              <TextInput value={title} onChange={setTitle} />
            </Field>
            <Field label={'문서 본문'} wide>
              <TextInput value={body} onChange={setBody} multiline />
            </Field>
            <Field label={'연계 업무 유형'} required>
              <TextInput value={linkedBusinessType} onChange={setLinkedBusinessType} />
            </Field>
            <Field label={'연계 업무 식별자'} required>
              <NumberInput value={linkedBusinessId} onChange={setLinkedBusinessId} />
            </Field>
          </Form>
        </Drawer>
      )}
    </div>
  );
}
